diff_context.after:
            r_copy["section"] = section_name
            all_rows.append(r_copy)

    if not args.no_sort:
        # sorting is handled inside render_one_big_table
        pass

    output_text = render_one_big_table(all_rows) + "\n"

    try:
        if args.output == "-":
            sys.stdout.write(output_text)
        else:
            with open(args.output, "w", encoding="utf-8") as fh:
                fh.write(output_text)
    except Exception as exc:
        print(f"Failed to write output {args.output!r}: {exc}", file=sys.stderr)
        return 4

    return 0


if __name__ == "__main__":
    raise SystemExit(main())
